      summary: "형님 온다 형님 온다 분고개로 형님 온다 하며 사촌 형님을 맞는 데서 시작합니다. 시집살이가 어떠하냐고 묻자 형님은 시집살이 개집살이라 답하며 고추와 당초보다 맵다고 합니다. 시아버지는 호랑새요 시어머니는 꾸중새요 동서는 할림새요 시누이는 뾰족새라 하고, 삼 년 만에 배꽃 같던 얼굴이 호박꽃이 되었다고 한탄합니다. 그러면서도 끝에는 자식들을 오리·거위에 비기며 웃음으로 넘깁니다.",
