                    { title: "고슴도치 엑스", author: "노인경 글/그림", tech: "찬반패널토론", topic: "자신을 보호하기 위해 날카로운 가시(방어기제)를 세우는 행동은 대인관계 형성에 득보다 실이 많은가?" },
                    { title: "슈퍼 거북", author: "유설화 글/그림", tech: "브레인라이팅 (Brainwriting)", topic: "타인의 기대와 좋은 평판을 유지하기 위해 자신의 본성과 자유를 희생하는 삶은 가치 있는가?" },
                    { title: "나쁜 일이 있어도 나쁜 날은 아니야", author: "정문정 글, 피도크 그림", tech: "PMI 토론", topic: "안 좋은 일 몇 가지가 있었다고 해서 그날 하루 전체를 '나쁜 날'이라고 말해도 되는가?" },
                    { title: "문 밖에 여전히 사자가 있다", author: "윤아해 글, 조원희 그림", tech: "가치수직선 토론", topic: "빠르게 돌파하는 용기와 자기 속도로 나아가는 용기, 무엇이 더 용기다운가?" }
